export const GOAL8_PROFILE_ID='ERP-GOAL8-20261007';
export const sqlHash=s=>createHash('sha256').update(s,'utf16le').digest('hex').toUpperCase();
const sha=s=>createHash('sha256').update(s).digest('hex').toUpperCase();
const lit=s=>"N'"+s.replaceAll("'","''")+"'";
const fail="THROW 51280,'GOAL8_EXACT_PROFILE_REQUIRED',1;";
const identity="IF DB_NAME() COLLATE Latin1_General_100_BIN2<>N'MELISA_ERP_SIRKET_TEST_20260929_01' OR CONVERT(nvarchar(128),SERVERPROPERTY('ServerName')) COLLATE Latin1_General_100_BIN2<>N'Semih\\MELISADEV' THROW 51280,'GOAL8_WRONG_DATABASE',1;";
const profileIntent="EXISTS(SELECT 1 FROM dbo.work_trade_intents n JOIN dbo.goal8_day_scope s ON s.id=1 WHERE n.session_id=@@SPID AND JSON_VALUE(n.payload_json,'$.testProfile')=s.run_id AND JSON_VALUE(n.payload_json,'$.testDayId')=LOWER(CONVERT(varchar(36),s.day_id)))";
const dayIntent="EXISTS(SELECT 1 FROM dbo.goal8_day_intents n JOIN dbo.goal8_day_scope s ON s.day_id=n.day_id WHERE n.session_id=@@SPID AND n.transaction_id=CURRENT_TRANSACTION_ID() AND s.sealed=1)";
const proofColumns=prefix=>`CONVERT(varchar(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.${prefix}ready'))),2) readyHash,CONVERT(varchar(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.${prefix}context'))),2) contextHash,CONVERT(varchar(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.${prefix}effects'))),2) effectsHash`;
const profileJson="JSON_QUERY((SELECT s.run_id id,LOWER(CONVERT(varchar(36),s.day_id)) dayId,CAST(s.sealed AS bit) sealed,CAST(1 AS bit) synthetic,N'325503' productId,N'13370' supplierId,N'30598' customerId,CONVERT(varchar(20),s.account_id) accountId,N'TRY' currency,s.definition_hash definitionHash FOR JSON PATH,WITHOUT_ARRAY_WRAPPER)) testProfile";
const proc=(name,args,body)=>`CREATE PROCEDURE dbo.${name} ${args} WITH EXECUTE AS OWNER AS BEGIN SET NOCOUNT ON; ${identity}\n${body}\nEND;`;
function inject(def,body){const match=/\bAS\s+BEGIN\b/i.exec(def);if(!match)throw Error('GOAL8_UNKNOWN_MODULE_HEADER');const at=match.index+match[0].length;return def.slice(0,at)+'\n/* Goal8 additive exact branch; original body follows. */\n'+body+'\n'+def.slice(at);}
function parameter(def,name,args){const old=`CREATE PROCEDURE dbo.${name}`;if(!def.startsWith(old))throw Error('GOAL8_UNKNOWN_PROCEDURE_HEADER');return def.replace(/ WITH EXECUTE AS OWNER AS BEGIN/,args+' WITH EXECUTE AS OWNER AS BEGIN');}
function nightBranch(def){const at=def.indexOf('/* ERP-NIGHT-20261006:');const end=def.indexOf('\nRETURN; END;',at);if(at<0||end<0)throw Error('GOAL8_NIGHT_BRANCH_MISSING');return def.slice(at,end+'\nRETURN; END;'.length);}
function tradeCopy(text){return text.replaceAll('dbo.work_trade_scope','dbo.goal8_day_scope').replaceAll('dbo.work_trade_products','dbo.goal8_day_quotes').replaceAll('EXEC dbo.work_trade_assert_ready;','EXEC dbo.goal8_day_assert_scope;').replaceAll("N'2026-10-06'","N'2026-10-07'").replaceAll("N'TEST-NIGHT-20261006-P1'","N'TEST-V70-GOODS-P'").replaceAll("N'TEST-NIGHT-20261006-P2'","N'TEST-FINISH-GOODS-P2'").replaceAll('BETWEEN 0 AND p.initial_stock','BETWEEN 0 AND 40');}
function immutable(columns,table,allowed){const names=columns.filter(c=>c.schemaName==='dbo'&&c.tableName===table&&!c.is_computed&&!['timestamp','rowversion'].includes(c.type)&&!allowed.includes(c.name)).map(c=>c.name);if(names.length<3||names.some(n=>! /^[a-zA-Z0-9_]+$/.test(n)))throw Error('GOAL8_COLUMN_CONTRACT');return `NOT EXISTS(SELECT ${names.map(n=>`i.[${n}]`).join(',')} EXCEPT SELECT ${names.map(n=>`d.[${n}]`).join(',')})`;}
const schema=`CREATE TABLE dbo.goal8_day_scope(id int NOT NULL PRIMARY KEY CHECK(id=1),run_id nvarchar(40) NOT NULL CHECK(run_id=N'ERP-GOAL8-20261007'),day_id uniqueidentifier NOT NULL UNIQUE,sealed bit NOT NULL,definition_hash char(64) NOT NULL,customer_id bigint NOT NULL CHECK(customer_id=30598),supplier_id bigint NOT NULL CHECK(supplier_id=13370),account_id bigint NOT NULL REFERENCES dbo.finance_accounts(id),currency nvarchar(3) NOT NULL CHECK(currency=N'TRY'),document_date date NOT NULL CHECK(document_date=CONVERT(date,N'2026-10-07')),max_total decimal(18,4) NOT NULL CHECK(max_total=500),max_quantity int NOT NULL CHECK(max_quantity=5),max_operations int NOT NULL CHECK(max_operations=30));
CREATE TABLE dbo.goal8_day_quotes(product_id bigint NOT NULL PRIMARY KEY CHECK(product_id IN(301985,325503)),stock_code nvarchar(80) NOT NULL UNIQUE,name nvarchar(200) NOT NULL,barcode nvarchar(80) NULL,initial_stock decimal(18,3) NOT NULL,unit nvarchar(20) NOT NULL CHECK(unit=N'ADET'),unit_price decimal(18,8) NOT NULL,cost decimal(18,4) NOT NULL,price_id bigint NOT NULL UNIQUE,CHECK((product_id=301985 AND unit_price=100 AND cost=60 AND price_id=900000301985) OR(product_id=325503 AND unit_price=120 AND cost=80 AND price_id=900000325503)));
CREATE TABLE dbo.goal8_day_intents(session_id int NOT NULL PRIMARY KEY,transaction_id bigint NOT NULL,day_id uniqueidentifier NOT NULL REFERENCES dbo.goal8_day_scope(day_id),request_id uniqueidentifier NOT NULL UNIQUE,actor_id bigint NOT NULL CHECK(actor_id=16),operation nvarchar(30) NOT NULL CHECK(operation IN(N'payment',N'payment_cancel',N'daily_purchase',N'daily_count')),payload_json nvarchar(max) NOT NULL CHECK(ISJSON(payload_json)=1));
CREATE TABLE dbo.goal8_day_manifest(name sysname NOT NULL PRIMARY KEY,definition_hash char(64) NOT NULL);
CREATE TABLE dbo.goal8_day_history(request_id uniqueidentifier NOT NULL PRIMARY KEY,day_id uniqueidentifier NOT NULL REFERENCES dbo.goal8_day_scope(day_id),operation nvarchar(30) NOT NULL,entity_id bigint NOT NULL,payload_json nvarchar(max) NOT NULL CHECK(ISJSON(payload_json)=1),response_json nvarchar(max) NOT NULL CHECK(ISJSON(response_json)=1));`;
const immutableTrigger=table=>`CREATE TRIGGER dbo.goal8_immutable_${table} ON dbo.${table} WITH EXECUTE AS OWNER AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON; ${identity} IF EXISTS(SELECT 1 FROM inserted) OR EXISTS(SELECT 1 FROM deleted) ${fail} END;`;
const batchView=`CREATE VIEW dbo.goal8_day_purchase_sources AS SELECT p.id invoice_id,i.id item_id,l.receipt_line_id,b.id receipt_id,i.product_id,i.quantity,i.line_total,p.supplier_id,p.document_no,p.document_date,p.status,p.account_amount,p.grand_total
FROM dbo.goal8_day_scope s JOIN dbo.test_goods_batches b ON b.note=N'GOAL8:'+LOWER(CONVERT(varchar(36),s.day_id)) AND b.supplier_id=s.supplier_id AND b.state=N'accepted' AND b.created_by IN(15,16) AND b.decided_by=16 AND b.warehouse_id=1
JOIN dbo.test_goods_batch_lines g ON g.batch_id=b.id AND g.product_id=325503 AND g.unit=N'ADET' AND g.unit_factor=1
JOIN dbo.test_purchase_batch_links l ON l.receipt_line_id=g.id JOIN dbo.purchase_invoice_items i ON i.id=l.invoice_item_id AND i.purchase_invoice_id=l.invoice_id AND i.product_id=g.product_id AND i.quantity=l.quantity AND i.purchase_price=80 AND i.line_discount_rate=0 AND i.currency_code=N'TRY' AND i.line_total=i.quantity*80 AND i.line_total_try=i.line_total
JOIN dbo.test_purchase_batch_drafts d ON d.invoice_id=l.invoice_id AND d.batch_id=b.id AND d.state=N'linked'
JOIN dbo.purchase_invoices p ON p.id=l.invoice_id AND p.supplier_id=s.supplier_id AND p.document_no LIKE N'TSTB-G8-%' AND p.document_date=s.document_date AND p.document_currency=N'TRY' AND p.account_currency=N'TRY' AND p.exchange_rate_snapshot=1 AND p.account_exchange_rate_snapshot=1 AND p.grand_total=p.account_amount AND p.grand_total=p.amount_try AND p.source_record_key IS NULL AND p.migration_run_id IS NULL
WHERE s.sealed=1 AND (SELECT COUNT(*) FROM dbo.purchase_invoice_items x WHERE x.purchase_invoice_id=p.id)=1 AND i.quantity BETWEEN 1 AND 5 AND i.quantity<=g.quantity;`;
function scopeDefinition(seal){return proc('goal8_day_assert_scope','',`
IF (SELECT COUNT(*) FROM dbo.goal8_day_scope)<>1 OR NOT EXISTS(SELECT 1 FROM dbo.goal8_day_scope WHERE id=1 AND sealed=1 AND definition_hash=${lit(seal)}) ${fail}
IF (SELECT COUNT(*) FROM dbo.goal8_day_quotes)<>2 OR EXISTS(SELECT 1 FROM dbo.goal8_day_quotes q LEFT JOIN dbo.products p ON p.id=q.product_id WHERE p.id IS NULL OR p.stock_code<>q.stock_code OR p.name<>q.name OR p.unit<>N'ADET' OR p.currency_code<>N'TRY' OR p.supplier_id<>13370 OR p.average_cost_try<>q.cost OR p.is_active<>1 OR p.is_deleted<>0 OR p.source_record_key IS NOT NULL OR p.migration_run_id IS NOT NULL OR p.current_stock_qty NOT BETWEEN 0 AND 40 OR EXISTS(SELECT 1 FROM erp_migration.accepted_price_products a WHERE a.product_id=p.id)) ${fail}
IF NOT EXISTS(SELECT 1 FROM dbo.suppliers WHERE id=13370 AND supplier_code=N'TEST-V70-GOODS-S' AND currency_code=N'TRY' AND is_active=1 AND is_deleted=0 AND source_record_key IS NULL AND migration_run_id IS NULL) OR NOT EXISTS(SELECT 1 FROM dbo.customers WHERE id=30598 AND customer_code=N'TEST-NIGHT-20261006-C' AND currency_code=N'TRY' AND is_active=1 AND is_deleted=0 AND source_record_key IS NULL AND migration_run_id IS NULL) OR NOT EXISTS(SELECT 1 FROM dbo.goal8_day_scope s JOIN dbo.finance_accounts a ON a.id=s.account_id WHERE a.account_code=N'TEST-NIGHT-20261006-K' AND a.currency_code=N'TRY' AND a.account_type=N'cash' AND a.opening_balance=0 AND a.source_record_key IS NULL AND a.migration_run_id IS NULL AND a.current_balance BETWEEN 0 AND 15000) ${fail}
IF EXISTS(SELECT 1 FROM erp_migration.operation_quarantine_holds WHERE(entity=N'product' AND native_id IN(301985,325503)) OR(entity=N'supplier' AND native_id=13370) OR(entity=N'customer' AND native_id=30598)) ${fail}
IF NOT EXISTS(SELECT 1 FROM dbo.users u JOIN dbo.roles r ON r.id=u.role_id WHERE u.id=15 AND u.is_active=1 AND r.code=N'isolated_test_sales' AND r.is_active=1) OR NOT EXISTS(SELECT 1 FROM dbo.users u JOIN dbo.roles r ON r.id=u.role_id WHERE u.id=16 AND u.is_active=1 AND r.code=N'isolated_test_ilker' AND r.is_active=1) ${fail}
IF EXISTS(SELECT 1 FROM dbo.goal8_day_manifest m WHERE OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+m.name)) IS NULL OR m.definition_hash<>CONVERT(varchar(64),HASHBYTES('SHA2_256',OBJECT_DEFINITION(OBJECT_ID(N'dbo.'+m.name))),2) OR(OBJECTPROPERTY(OBJECT_ID(N'dbo.'+m.name),'IsTrigger')=1 AND OBJECTPROPERTY(OBJECT_ID(N'dbo.'+m.name),'ExecIsTriggerDisabled')<>0)) ${fail}`);}
function historyDefinition(){return proc('goal8_day_assert_history','',`EXEC dbo.goal8_day_assert_scope;
IF EXISTS(SELECT 1 FROM dbo.goal8_day_quotes q JOIN dbo.products p ON p.id=q.product_id WHERE p.current_stock_qty<>q.initial_stock+COALESCE((SELECT SUM(m.quantity_net) FROM dbo.stock_movements m WHERE m.product_id=q.product_id),0)) ${fail}
IF EXISTS(SELECT 1 FROM dbo.goal8_day_scope s JOIN dbo.customers c ON c.id=s.customer_id JOIN dbo.finance_accounts a ON a.id=s.account_id WHERE c.balance<>COALESCE((SELECT SUM(m.balance_effect) FROM dbo.customer_movements m WHERE m.customer_id=c.id),0) OR a.current_balance<>COALESCE((SELECT SUM(CASE m.direction WHEN N'in' THEN m.amount ELSE -m.amount END) FROM dbo.finance_account_movements m WHERE m.account_id=a.id),0)) ${fail}
IF EXISTS(SELECT 1 FROM dbo.goal8_day_history h JOIN dbo.goal8_day_scope s ON s.day_id=h.day_id WHERE JSON_VALUE(h.payload_json,'$.testProfile')<>s.run_id OR JSON_VALUE(h.payload_json,'$.testDayId')<>LOWER(CONVERT(varchar(36),s.day_id)) OR TRY_CONVERT(uniqueidentifier,JSON_VALUE(h.payload_json,'$.requestId')) IS NULL OR TRY_CONVERT(uniqueidentifier,JSON_VALUE(h.payload_json,'$.requestId'))<>h.request_id OR h.operation NOT IN(N'payment',N'payment_cancel',N'daily_purchase',N'daily_count')) ${fail}
IF EXISTS(SELECT 1 FROM dbo.work_supplier_payment_requests j WHERE JSON_VALUE(j.payload_json,'$.testProfile')=N'ERP-GOAL8-20261007' AND NOT EXISTS(SELECT 1 FROM dbo.goal8_day_scope s JOIN dbo.supplier_movements m ON m.id=j.movement_id JOIN dbo.goal8_day_purchase_sources v ON v.invoice_id=m.purchase_invoice_id JOIN dbo.finance_account_movements f ON f.party_type=N'supplier' AND f.party_movement_id=m.id AND f.source_type=m.movement_type WHERE JSON_VALUE(j.payload_json,'$.testDayId')=LOWER(CONVERT(varchar(36),s.day_id)) AND j.actor_id=16 AND m.created_by=16 AND m.supplier_id=s.supplier_id AND f.account_id=s.account_id AND m.movement_type=j.operation AND m.amount>0 AND m.amount<=500 AND m.account_currency=N'TRY' AND m.currency_code=N'TRY' AND m.account_amount=m.amount AND m.amount_try=m.amount AND m.document_exchange_rate_snapshot=1 AND m.account_exchange_rate_snapshot=1 AND m.document_date=s.document_date AND m.balance_effect=CASE j.operation WHEN N'payment' THEN -m.amount ELSE m.amount END AND f.amount=m.amount AND f.currency_code=N'TRY' AND f.direction=CASE j.operation WHEN N'payment' THEN N'out' ELSE N'in' END AND f.created_by=16 AND (SELECT COUNT(*) FROM dbo.finance_account_movements x WHERE x.party_type=N'supplier' AND x.party_movement_id=m.id)=1 AND j.payload_hash=CONVERT(varchar(64),HASHBYTES('SHA2_256',j.payload_json),2))) ${fail}
IF EXISTS(SELECT 1 FROM dbo.goal8_day_sales_links l JOIN dbo.sales_invoices v ON v.id=l.invoice_id JOIN dbo.goal8_day_scope s ON s.id=1 WHERE v.customer_id<>s.customer_id OR v.document_date<>s.document_date OR v.document_currency<>N'TRY' OR v.customer_currency<>N'TRY' OR v.exchange_rate_snapshot<>1 OR v.grand_total<>v.subtotal OR v.grand_total<>v.amount_try OR v.grand_total NOT BETWEEN 0.0001 AND 500 OR v.source_record_key IS NOT NULL OR v.migration_run_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM dbo.sales_invoice_items i WHERE i.sales_invoice_id=v.id) OR EXISTS(SELECT 1 FROM dbo.sales_invoice_items i WHERE i.sales_invoice_id=v.id AND NOT EXISTS(SELECT 1 FROM dbo.goal8_day_quotes q WHERE q.product_id=i.product_id AND q.unit_price=i.unit_price AND q.cost=i.average_cost_try_snapshot AND i.line_total=i.quantity*q.unit_price AND i.quantity BETWEEN 1 AND 5 AND i.quantity=FLOOR(i.quantity)))) ${fail}`);}
function paymentContextDefinition(){return proc('goal8_day_payment_context','@actor_id bigint',`EXEC dbo.goal8_day_assert_history;
IF @actor_id<>16 OR (SELECT COUNT(*) FROM dbo.permissions p JOIN dbo.users u ON u.role_id=p.role_id WHERE u.id=@actor_id AND p.can_view=1 AND p.permission_key IN(N'finance.view',N'supplier.view'))<>2 ${fail}
SELECT (SELECT ${profileJson},CONVERT(varchar(20),@actor_id) actorId,N'isolated_test_ilker' roleCode,
JSON_QUERY((SELECT N'['+STRING_AGG(CONVERT(nvarchar(max),N'"'+STRING_ESCAPE(p.permission_key,'json')+N'"'),N',') WITHIN GROUP(ORDER BY p.permission_key)+N']' FROM dbo.permissions p JOIN dbo.users u ON u.role_id=p.role_id WHERE u.id=@actor_id AND p.can_view=1)) permissions,CONVERT(char(10),s.document_date,23) documentDate,N'500.0000' maxAmountExact4,30 maxPayments,
JSON_QUERY((SELECT CONVERT(varchar(20),p.id) id,p.supplier_code code,p.name,p.currency_code currency,CONVERT(varchar(40),CAST(p.balance AS decimal(18,4))) balanceExact4,CAST(1 AS bit) snapshotVerified,N'invoice' debtKind,
JSON_QUERY(COALESCE((SELECT CONVERT(varchar(20),v.invoice_id) id,CONVERT(varchar(20),v.receipt_id) receiptId,N'work-goal8-batch-receipt' receiptKind,v.document_no number,v.status,CONVERT(char(10),v.document_date,23) documentDate,N'TRY' documentCurrency,CONVERT(varchar(40),CAST(v.grand_total AS decimal(18,4))) documentAmountExact4,N'TRY' accountCurrency,CONVERT(varchar(40),CAST(v.account_amount AS decimal(18,4))) accountAmountExact4,CONVERT(varchar(40),CAST(COALESCE(pay.paid,0) AS decimal(18,4))) paidExact4,CONVERT(varchar(40),CAST(COALESCE(ret.returned,0) AS decimal(18,4))) returnedExact4,CONVERT(varchar(40),CAST(v.account_amount-COALESCE(pay.paid,0)-COALESCE(ret.returned,0) AS decimal(18,4))) remainingExact4 FROM dbo.goal8_day_purchase_sources v OUTER APPLY(SELECT SUM(-m.balance_effect) paid FROM dbo.supplier_movements m WHERE m.purchase_invoice_id=v.invoice_id AND m.movement_type IN(N'payment',N'payment_cancel')) pay OUTER APPLY(SELECT SUM(CASE r.status WHEN N'finalized' THEN r.account_amount ELSE 0 END) returned FROM dbo.invoice_returns r WHERE r.source_purchase_invoice_id=v.invoice_id AND r.kind=N'purchase') ret WHERE v.status=N'finalized' FOR JSON PATH),N'[]')) invoices FROM dbo.suppliers p WHERE p.id=s.supplier_id FOR JSON PATH)) suppliers,
JSON_QUERY((SELECT CONVERT(varchar(20),a.id) id,a.account_code code,a.account_name name,a.account_type type,a.currency_code currency,N'0.0000' openingBalanceExact4,CONVERT(varchar(40),CAST(a.current_balance AS decimal(18,4))) balanceExact4,CAST(1 AS bit) openingVerified FROM dbo.finance_accounts a WHERE a.id=s.account_id FOR JSON PATH)) accounts,JSON_QUERY(N'[]') rates,
JSON_QUERY(COALESCE((SELECT CONVERT(varchar(20),m.id) id,CONVERT(varchar(20),m.supplier_id) supplierId,CONVERT(varchar(20),f.account_id) accountId,CONVERT(varchar(20),m.purchase_invoice_id) invoiceId,CONVERT(varchar(20),v.receipt_id) receiptId,N'work-goal8-batch-receipt' receiptKind,v.document_no invoiceNumber,m.movement_type kind,f.direction,m.currency_code currency,CONVERT(varchar(40),CAST(m.amount AS decimal(18,4))) amountExact4,m.account_currency accountCurrency,CONVERT(varchar(40),CAST(m.account_amount AS decimal(18,4))) accountAmountExact4,CONVERT(varchar(40),CAST(m.amount_try AS decimal(18,4))) amountTryExact4,CONVERT(varchar(40),CAST(m.document_exchange_rate_snapshot AS decimal(18,8))) documentRateExact8,CONVERT(varchar(40),CAST(m.account_exchange_rate_snapshot AS decimal(18,8))) accountRateExact8,CONVERT(char(10),m.document_date,23) documentDate,COALESCE(f.description,N'') description,f.document_no number,CONVERT(varchar(20),j.original_id) originalId,CONVERT(varchar(20),cancel.movement_id) reversedById,N'work' ownership,CAST(CASE WHEN j.operation=N'payment' AND cancel.movement_id IS NULL THEN 1 ELSE 0 END AS bit) canCancel FROM dbo.work_supplier_payment_requests j JOIN dbo.supplier_movements m ON m.id=j.movement_id JOIN dbo.goal8_day_purchase_sources v ON v.invoice_id=m.purchase_invoice_id JOIN dbo.finance_account_movements f ON f.party_type=N'supplier' AND f.party_movement_id=m.id AND f.source_type=m.movement_type LEFT JOIN dbo.work_supplier_payment_requests cancel ON cancel.original_id=m.id WHERE JSON_VALUE(j.payload_json,'$.testDayId')=LOWER(CONVERT(varchar(36),s.day_id)) ORDER BY m.id FOR JSON PATH,INCLUDE_NULL_VALUES),N'[]')) payments FROM dbo.goal8_day_scope s WHERE s.id=1 FOR JSON PATH,WITHOUT_ARRAY_WRAPPER) context_json,${proofColumns('usp_work_supplier_payment_')};`);}
function beginDefinition(){return proc('goal8_day_begin','@request_id uniqueidentifier,@actor_id bigint,@operation nvarchar(30),@payload nvarchar(max)',`EXEC dbo.goal8_day_assert_history;
IF @request_id IS NULL OR @actor_id<>16 OR ISJSON(@payload)<>1 OR JSON_VALUE(@payload,'$.actorId')<>N'16' OR JSON_VALUE(@payload,'$.operation')<>@operation OR TRY_CONVERT(uniqueidentifier,JSON_VALUE(@payload,'$.requestId')) IS NULL OR TRY_CONVERT(uniqueidentifier,JSON_VALUE(@payload,'$.requestId'))<>@request_id OR JSON_VALUE(@payload,'$.requestId')<>LOWER(CONVERT(varchar(36),@request_id)) OR NOT EXISTS(SELECT 1 FROM dbo.goal8_day_scope s WHERE JSON_VALUE(@payload,'$.testProfile')=s.run_id AND JSON_VALUE(@payload,'$.testDayId')=LOWER(CONVERT(varchar(36),s.day_id))) ${fail}
IF @operation NOT IN(N'payment',N'payment_cancel',N'daily_purchase',N'daily_count') OR EXISTS(SELECT 1 FROM dbo.goal8_day_intents WHERE session_id=@@SPID OR request_id=@request_id) ${fail}
IF @operation=N'payment' AND NOT EXISTS(SELECT 1 FROM dbo.goal8_day_scope s JOIN dbo.goal8_day_purchase_sources v ON v.supplier_id=s.supplier_id WHERE v.invoice_id=TRY_CONVERT(bigint,JSON_VALUE(@payload,'$.invoiceId')) AND v.status=N'finalized' AND JSON_VALUE(@payload,'$.supplierId')=N'13370' AND TRY_CONVERT(bigint,JSON_VALUE(@payload,'$.accountId'))=s.account_id AND JSON_VALUE(@payload,'$.currency')=N'TRY' AND TRY_CONVERT(decimal(18,4),JSON_VALUE(@payload,'$.amountExact4')) BETWEEN 0.0001 AND 500 AND JSON_VALUE(@payload,'$.documentDate')=CONVERT(char(10),s.document_date,23)) ${fail}
IF @operation=N'payment_cancel' AND NOT EXISTS(SELECT 1 FROM dbo.work_supplier_payment_requests j JOIN dbo.goal8_day_scope s ON JSON_VALUE(j.payload_json,'$.testDayId')=LOWER(CONVERT(varchar(36),s.day_id)) WHERE j.movement_id=TRY_CONVERT(bigint,JSON_VALUE(@payload,'$.id')) AND j.operation=N'payment' AND NOT EXISTS(SELECT 1 FROM dbo.work_supplier_payment_requests x WHERE x.original_id=j.movement_id)) ${fail}
IF @operation IN(N'daily_purchase',N'daily_count') AND NOT EXISTS(SELECT 1 FROM dbo.test_daily_drafts d JOIN dbo.goal8_day_scope s ON s.id=1 WHERE d.id=TRY_CONVERT(bigint,JSON_VALUE(@payload,'$.id')) AND d.state=N'pending' AND d.created_by IN(15,16) AND((@operation=N'daily_purchase' AND d.flow=N'purchase' AND d.kind=N'invoice-return' AND JSON_VALUE(d.payload_json,'$.documentDate')=CONVERT(char(10),s.document_date,23) AND EXISTS(SELECT 1 FROM dbo.goal8_day_purchase_sources v WHERE v.invoice_id=TRY_CONVERT(bigint,JSON_VALUE(d.payload_json,'$.sourceInvoiceId')) AND v.status=N'finalized' AND v.product_id=325503)) OR(@operation=N'daily_count' AND d.flow=N'count' AND d.kind=N'count' AND JSON_VALUE(d.payload_json,'$.date')=CONVERT(char(10),s.document_date,23) AND JSON_QUERY(d.payload_json,'$.unknownScans')=N'[]' AND NOT EXISTS(SELECT 1 FROM OPENJSON(d.payload_json,'$.lines') WITH(productId bigint,physical decimal(18,3),system decimal(18,3)) l WHERE l.productId<>325503 OR l.physical<>l.system)))) ${fail}
INSERT dbo.goal8_day_intents SELECT @@SPID,CURRENT_TRANSACTION_ID(),day_id,@request_id,@actor_id,@operation,@payload FROM dbo.goal8_day_scope WHERE id=1;`);}
function effectsDefinition(){return proc('goal8_day_payment_effects','@request_id uniqueidentifier,@daily bit=0,@end bit=0',`EXEC dbo.goal8_day_assert_history;
DECLARE @op nvarchar(30),@payload nvarchar(max),@day uniqueidentifier,@entity bigint,@response nvarchar(max);
SELECT @op=operation,@payload=payload_json,@day=day_id FROM dbo.goal8_day_intents WHERE session_id=@@SPID AND transaction_id=CURRENT_TRANSACTION_ID() AND request_id=@request_id;
IF @op IS NULL ${fail}
IF @daily=0 BEGIN
 IF @op NOT IN(N'payment',N'payment_cancel') OR NOT EXISTS(SELECT 1 FROM dbo.work_supplier_payment_requests j JOIN dbo.supplier_movements m ON m.id=j.movement_id WHERE j.request_id=@request_id AND j.actor_id=16 AND j.operation=@op AND j.payload_json=@payload AND JSON_VALUE(j.response_json,'$.replayed')=N'false' AND JSON_VALUE(j.response_json,'$.requestId')=LOWER(CONVERT(varchar(36),@request_id)) AND TRY_CONVERT(bigint,JSON_VALUE(j.response_json,'$.payment.id'))=m.id AND TRY_CONVERT(bigint,JSON_VALUE(j.response_json,'$.payment.supplierId'))=13370 AND TRY_CONVERT(decimal(18,4),JSON_VALUE(j.response_json,'$.payment.amountExact4'))=m.amount AND NOT EXISTS(SELECT 1 FROM dbo.supplier_movements x WHERE x.id=m.id AND NOT EXISTS(SELECT 1 FROM dbo.audit_logs a WHERE a.entity_type=N'supplier_movement' AND a.entity_id=x.id AND a.actor_user_id=16))) ${fail}
 SELECT @entity=movement_id,@response=response_json FROM dbo.work_supplier_payment_requests WHERE request_id=@request_id;
END ELSE BEGIN
 IF @op NOT IN(N'daily_purchase',N'daily_count') OR NOT EXISTS(SELECT 1 FROM dbo.test_daily_requests j JOIN dbo.test_daily_drafts d ON d.id=TRY_CONVERT(bigint,JSON_VALUE(@payload,'$.id')) WHERE j.request_id=LOWER(CONVERT(varchar(36),@request_id)) AND j.actor_id=16 AND j.operation=N'approve' AND d.state=N'approved' AND d.decided_by=16 AND JSON_VALUE(d.payload_json,CASE @op WHEN N'daily_purchase' THEN '$.documentDate' ELSE '$.date' END)=N'2026-10-07') ${fail}
 SELECT @entity=TRY_CONVERT(bigint,JSON_VALUE(result_json,'$.id')) FROM dbo.test_daily_drafts WHERE id=TRY_CONVERT(bigint,JSON_VALUE(@payload,'$.id'));
 SELECT @response=response_json FROM dbo.test_daily_requests WHERE request_id=LOWER(CONVERT(varchar(36),@request_id));
 IF @op=N'daily_purchase' AND NOT EXISTS(SELECT 1 FROM dbo.invoice_returns r JOIN dbo.goal8_day_purchase_sources v ON v.invoice_id=r.source_purchase_invoice_id JOIN dbo.invoice_return_items i ON i.invoice_return_id=r.id AND i.source_purchase_item_id=v.item_id JOIN dbo.stock_movements m ON m.source_type=N'invoice_return' AND m.source_id=r.id AND m.product_id=i.product_id JOIN dbo.supplier_movements p ON p.invoice_return_id=r.id AND p.movement_type=N'purchase_return' WHERE r.id=@entity AND r.status=N'finalized' AND r.created_by=16 AND r.supplier_id=13370 AND r.kind=N'purchase' AND i.product_id=325503 AND i.quantity=1 AND i.unit_cost_try=80 AND r.amount=80 AND r.account_amount=80 AND r.amount_try=80 AND m.quantity_net=-1 AND m.unit_cost_try=80 AND m.currency_code=N'TRY' AND p.supplier_id=13370 AND p.balance_effect=-80 AND p.amount=80 AND p.account_currency=N'TRY' AND p.account_amount=80 AND p.document_exchange_rate_snapshot=1 AND p.account_exchange_rate_snapshot=1) ${fail}
END;
IF @entity IS NULL OR @response IS NULL ${fail}
IF @end=1 BEGIN INSERT dbo.goal8_day_history VALUES(@request_id,@day,@op,@entity,@payload,@response); DELETE dbo.goal8_day_intents WHERE session_id=@@SPID AND request_id=@request_id AND transaction_id=CURRENT_TRANSACTION_ID(); END;
SELECT CAST(1 AS bit) valid,${proofColumns('usp_work_supplier_payment_')};`);}

const currentReturnView=`CREATE VIEW dbo.goal8_day_current_return AS SELECT r.*,d.id daily_draft_id
FROM dbo.goal8_day_intents n JOIN dbo.goal8_day_scope s ON s.day_id=n.day_id JOIN dbo.test_daily_drafts d ON d.id=TRY_CONVERT(bigint,JSON_VALUE(n.payload_json,'$.id')) AND d.flow=N'purchase' AND d.kind=N'invoice-return' AND d.created_by IN(15,16) AND d.state IN(N'pending',N'approved')
JOIN dbo.invoice_returns r ON r.request_id=TRY_CONVERT(uniqueidentifier,JSON_VALUE(d.payload_json,'$.requestId')) AND r.source_purchase_invoice_id=TRY_CONVERT(bigint,JSON_VALUE(d.payload_json,'$.sourceInvoiceId'))
JOIN dbo.goal8_day_purchase_sources v ON v.invoice_id=r.source_purchase_invoice_id
WHERE n.session_id=@@SPID AND n.transaction_id=CURRENT_TRANSACTION_ID() AND n.operation=N'daily_purchase' AND n.actor_id=16 AND r.kind=N'purchase' AND r.status=N'finalized' AND r.supplier_id=13370 AND r.customer_id IS NULL AND r.source_sales_invoice_id IS NULL AND r.created_by=16 AND r.document_date=s.document_date AND r.document_currency=N'TRY' AND r.account_currency=N'TRY' AND r.exchange_rate_snapshot=1 AND r.account_exchange_rate_snapshot=1 AND r.amount=80 AND r.account_amount=80 AND r.amount_try=80 AND v.status=N'finalized';`;
const currentPaymentView=`CREATE VIEW dbo.goal8_day_current_payment AS SELECT m.* FROM dbo.goal8_day_intents n JOIN dbo.goal8_day_scope s ON s.day_id=n.day_id JOIN dbo.supplier_movements m ON m.supplier_id=s.supplier_id AND m.movement_type=n.operation AND m.created_by=16 AND m.document_date=s.document_date JOIN dbo.goal8_day_purchase_sources v ON v.invoice_id=m.purchase_invoice_id AND v.status=N'finalized'
WHERE n.session_id=@@SPID AND n.transaction_id=CURRENT_TRANSACTION_ID() AND n.actor_id=16 AND n.operation IN(N'payment',N'payment_cancel') AND m.currency_code=N'TRY' AND m.amount BETWEEN 0.0001 AND 500 AND m.balance_effect=CASE n.operation WHEN N'payment' THEN -m.amount ELSE m.amount END AND m.invoice_return_id IS NULL AND m.source_record_key IS NULL AND m.migration_run_id IS NULL
AND((n.operation=N'payment' AND m.purchase_invoice_id=TRY_CONVERT(bigint,JSON_VALUE(n.payload_json,'$.invoiceId')) AND m.amount=TRY_CONVERT(decimal(18,4),JSON_VALUE(n.payload_json,'$.amountExact4'))) OR(n.operation=N'payment_cancel' AND EXISTS(SELECT 1 FROM dbo.work_supplier_payment_requests j JOIN dbo.supplier_movements o ON o.id=j.movement_id WHERE j.movement_id=TRY_CONVERT(bigint,JSON_VALUE(n.payload_json,'$.id')) AND j.operation=N'payment' AND JSON_VALUE(j.payload_json,'$.testDayId')=LOWER(CONVERT(varchar(36),s.day_id)) AND m.purchase_invoice_id=o.purchase_invoice_id AND m.amount=o.amount)))
AND(m.account_currency IS NULL OR m.account_currency=N'TRY') AND(m.account_amount IS NULL OR m.account_amount=m.amount) AND(m.amount_try IS NULL OR m.amount_try=m.amount) AND(m.document_exchange_rate_snapshot IS NULL OR m.document_exchange_rate_snapshot=1) AND(m.account_exchange_rate_snapshot IS NULL OR m.account_exchange_rate_snapshot=1);`;
function nativeDayPrefix(table,columns){
 const stagedPayment="EXISTS(SELECT 1 FROM dbo.goal8_day_current_payment p WHERE p.id=i.id)";
 const returnMovement="EXISTS(SELECT 1 FROM dbo.goal8_day_current_return r WHERE r.id=i.invoice_return_id AND i.supplier_id=13370 AND i.purchase_invoice_id IS NULL AND i.movement_type=N'purchase_return' AND i.amount=r.amount AND i.currency_code=N'TRY' AND i.balance_effect=-r.account_amount AND i.account_currency=N'TRY' AND i.account_amount=r.account_amount AND i.amount_try=r.amount_try AND i.document_exchange_rate_snapshot=1 AND i.account_exchange_rate_snapshot=1 AND i.document_date=r.document_date AND i.created_by=16 AND i.source_record_key IS NULL AND i.migration_run_id IS NULL)";
 let body;
 if(table==='supplier_movements')body=`IF EXISTS(SELECT 1 FROM inserted i WHERE NOT(${stagedPayment} OR ${returnMovement})) OR EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.id=d.id WHERE i.id IS NULL OR NOT(${immutable(columns,table,['account_currency','account_amount','amount_try','document_exchange_rate_snapshot','account_exchange_rate_snapshot'])})) ${fail}`;
 if(table==='suppliers')body=`IF EXISTS(SELECT 1 FROM inserted i LEFT JOIN deleted d ON d.id=i.id WHERE d.id IS NULL OR i.id<>13370 OR NOT(${immutable(columns,table,['balance','updated_at'])}) OR i.balance<>COALESCE((SELECT SUM(m.balance_effect) FROM dbo.supplier_movements m WHERE m.supplier_id=i.id),0)) OR EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.id=d.id WHERE i.id IS NULL) ${fail}`;
 if(table==='finance_account_movements')body=`IF EXISTS(SELECT 1 FROM deleted) OR EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.goal8_day_current_payment p JOIN dbo.goal8_day_scope s ON s.id=1 WHERE i.account_id=s.account_id AND i.party_type=N'supplier' AND i.party_movement_id=p.id AND i.source_type=p.movement_type AND i.direction=CASE p.movement_type WHEN N'payment' THEN N'out' ELSE N'in' END AND i.amount=p.amount AND i.currency_code=N'TRY' AND i.created_by=16 AND i.document_date=s.document_date AND i.payment_method=N'cash' AND i.source_record_key IS NULL AND i.migration_run_id IS NULL AND (SELECT COUNT(*) FROM dbo.finance_account_movements x WHERE x.party_type=i.party_type AND x.party_movement_id=i.party_movement_id)=1)) ${fail}`;
 if(table==='finance_accounts')body=`IF EXISTS(SELECT 1 FROM inserted i LEFT JOIN deleted d ON d.id=i.id WHERE d.id IS NULL OR NOT EXISTS(SELECT 1 FROM dbo.goal8_day_scope s WHERE s.account_id=i.id) OR NOT(${immutable(columns,table,['current_balance','updated_at'])}) OR i.current_balance NOT BETWEEN 0 AND 15000 OR i.current_balance<>COALESCE((SELECT SUM(CASE m.direction WHEN N'in' THEN m.amount ELSE -m.amount END) FROM dbo.finance_account_movements m WHERE m.account_id=i.id),0)) OR EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.id=d.id WHERE i.id IS NULL) ${fail}`;
 if(table==='products')body=`IF EXISTS(SELECT 1 FROM inserted i LEFT JOIN deleted d ON d.id=i.id WHERE d.id IS NULL OR i.id<>325503 OR i.average_cost_try<>80 OR NOT(${immutable(columns,table,['current_stock_qty','average_cost_try','updated_at'])}) OR i.current_stock_qty<>d.current_stock_qty-1 OR i.current_stock_qty<0 OR NOT EXISTS(SELECT 1 FROM dbo.goal8_day_current_return r JOIN dbo.invoice_return_items l ON l.invoice_return_id=r.id AND l.product_id=i.id AND l.quantity=1 AND l.unit_cost_try=80)) OR EXISTS(SELECT 1 FROM deleted d LEFT JOIN inserted i ON i.id=d.id WHERE i.id IS NULL) ${fail}`;
 if(table==='stock_movements')body=`IF EXISTS(SELECT 1 FROM deleted) OR EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.goal8_day_current_return r JOIN dbo.invoice_return_items l ON l.invoice_return_id=r.id AND l.product_id=i.product_id AND l.quantity=1 AND l.unit_cost_try=80 WHERE i.product_id=325503 AND i.source_type=N'invoice_return' AND i.source_id=r.id AND i.movement_type=N'out' AND i.quantity_in=0 AND i.quantity_out=1 AND i.quantity_net=-1 AND i.unit_cost_try=80 AND i.average_cost_try_after=80 AND i.unit_price=80 AND i.amount_try=-80 AND i.currency_code=N'TRY' AND i.supplier_id=13370 AND i.customer_id IS NULL AND i.created_by=16 AND i.document_date=r.document_date AND i.source_record_key IS NULL AND i.migration_run_id IS NULL)) ${fail}`;
 if(table==='invoice_returns')body=`IF EXISTS(SELECT 1 FROM deleted) OR EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.goal8_day_current_return r WHERE r.id=i.id)) ${fail}`;
 if(table==='audit_logs')body=`IF EXISTS(SELECT 1 FROM deleted) OR EXISTS(SELECT 1 FROM inserted i WHERE i.actor_user_id<>16 OR NOT((i.entity_type=N'supplier_movement' AND i.action IN(N'supplier_payment_created',N'supplier_payment_cancelled') AND EXISTS(SELECT 1 FROM dbo.goal8_day_current_payment p WHERE p.id=i.entity_id)) OR(i.entity_type=N'invoice_return' AND i.action=N'purchase_return_finalized' AND EXISTS(SELECT 1 FROM dbo.goal8_day_current_return r WHERE r.id=i.entity_id)) OR(i.entity_type=N'test_daily_draft' AND i.action=N'test_daily_approved' AND EXISTS(SELECT 1 FROM dbo.goal8_day_intents n JOIN dbo.test_daily_drafts d ON d.id=TRY_CONVERT(bigint,JSON_VALUE(n.payload_json,'$.id')) WHERE n.session_id=@@SPID AND n.transaction_id=CURRENT_TRANSACTION_ID() AND n.operation IN(N'daily_purchase',N'daily_count') AND d.id=i.entity_id AND d.state=N'approved' AND d.decided_by=16)))) ${fail}`;
 if(!body)return '';
 const ops=['products','stock_movements','invoice_returns'].includes(table)?"n.operation=N'daily_purchase'":table==='audit_logs'?"n.operation IN(N'payment',N'payment_cancel',N'daily_purchase',N'daily_count')":"n.operation IN(N'payment',N'payment_cancel',N'daily_purchase')";
 return `IF ${dayIntent} AND EXISTS(SELECT 1 FROM dbo.goal8_day_intents n WHERE n.session_id=@@SPID AND n.transaction_id=CURRENT_TRANSACTION_ID() AND ${ops}) BEGIN EXEC dbo.goal8_day_assert_scope; ${body} RETURN; END;`;
}
function countBranch(def){const at=def.indexOf('/* TEST_DAILY_COUNT_LINES_20261006:');const end=def.indexOf('\nEND;',at);if(at<0||end<0)throw Error('GOAL8_COUNT_PREFIX_MISSING');return `IF ${dayIntent} AND EXISTS(SELECT 1 FROM dbo.goal8_day_intents n WHERE n.session_id=@@SPID AND n.operation=N'daily_count') BEGIN\n`+def.slice(at,end+'\nEND;'.length).replaceAll("N'2026-10-06'","N'2026-10-07'").replace(/(?<!@)@[a-zA-Z]\w*/g,name=>'@g8'+name.slice(1))+'\nEND;';}
function closure(modules,changes){
 const alter=s=>s.replace(/^CREATE (PROCEDURE|TRIGGER|VIEW)/,(_,type)=>'ALTER '+type);
 for(const [name,body] of changes)changes.set(name,alter(body));
 const direct=new Map([...modules].map(([name,row])=>[name,changes.get(name)??row.definition]));
 for(let round=0;round<20;round++){
  let moved=false;
  const pairs=[...changes].map(([name,after])=>[modules.get(name).definitionHash,sqlHash(after)]).filter(([a,b])=>a!==b);
  // Recompute from the unexpanded body: hashes from an intermediate round must
  // never hide a later change to the same dependency.
  for(const [name,row] of modules){let definition=direct.get(name);for(const [before,after] of pairs)definition=definition.replaceAll(before,after);if(definition!==row.definition)definition=alter(definition);if(definition!==(changes.get(name)??row.definition)){changes.set(name,definition);moved=true;}}
  if(!moved)return;
 }
 throw Error('GOAL8_HASH_DEPENDENCY_CYCLE');
}

