 if(! /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(dayId??'')||exported?.identity?.server!=='Semih\\MELISADEV'||exported.identity.database!=='MELISA_ERP_SIRKET_TEST_20260929_01'||!Array.isArray(exported.modules)||!Array.isArray(exported.columns))throw Error('GOAL8_EXACT_EXPORT_AND_DAY_REQUIRED');
