 add(`CREATE TRIGGER dbo.goal8_day_history_guard ON dbo.goal8_day_history WITH EXECUTE AS OWNER AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON; ${identity} IF EXISTS(SELECT 1 FROM deleted) OR NOT(${dayIntent}) OR EXISTS(SELECT 1 FROM inserted i WHERE NOT EXISTS(SELECT 1 FROM dbo.goal8_day_intents n WHERE n.session_id=@@SPID AND n.transaction_id=CURRENT_TRANSACTION_ID() AND n.request_id=i.request_id AND n.day_id=i.day_id AND n.operation=i.operation AND n.payload_json=i.payload_json)) ${fail} END;`);
 add(`CREATE TRIGGER dbo.goal8_day_intents_guard ON dbo.goal8_day_intents WITH EXECUTE AS OWNER AFTER INSERT,UPDATE,DELETE AS BEGIN SET NOCOUNT ON; ${identity} IF EXISTS(SELECT 1 FROM inserted i WHERE i.session_id<>@@SPID OR i.transaction_id<>CURRENT_TRANSACTION_ID() OR i.actor_id<>16 OR JSON_VALUE(i.payload_json,'$.actorId')<>N'16' OR JSON_VALUE(i.payload_json,'$.operation')<>i.operation OR NOT EXISTS(SELECT 1 FROM dbo.goal8_day_scope s WHERE s.day_id=i.day_id AND s.sealed=1 AND JSON_VALUE(i.payload_json,'$.testProfile')=s.run_id AND JSON_VALUE(i.payload_json,'$.testDayId')=LOWER(CONVERT(varchar(36),s.day_id)))) OR EXISTS(SELECT 1 FROM deleted d WHERE EXISTS(SELECT 1 FROM inserted i WHERE i.session_id=d.session_id) OR d.session_id<>@@SPID OR d.transaction_id<>CURRENT_TRANSACTION_ID() OR NOT EXISTS(SELECT 1 FROM dbo.goal8_day_history h WHERE h.request_id=d.request_id AND h.payload_json=d.payload_json)) ${fail} END;`);
 // Same trusted writer context and virtual fixture quote; no product_prices mutation.
 let context=tradeCopy(modules.get('work_trade_get_context').definition).replace('CREATE PROCEDURE dbo.work_trade_get_context','CREATE PROCEDURE dbo.goal8_day_trade_context').replaceAll('JOIN dbo.product_prices r ON r.id=w.price_id','CROSS APPLY(SELECT w.price_id id,w.unit_price price) r');
