 effect=effect.split('\n').filter(line=>!line.startsWith('IF EXISTS(SELECT 1 FROM dbo.stock_movements m JOIN dbo.goal8_day_quotes')).join('\n');
 effect=effect.replace('dbo.goal8_day_scope s ON s.customer_id=m.customer_id WHERE NOT EXISTS','dbo.goal8_day_scope s ON s.customer_id=m.customer_id WHERE EXISTS(SELECT 1 FROM dbo.goal8_day_sales_links gl WHERE gl.invoice_id=m.sales_invoice_id) AND NOT EXISTS');add(effect);
